<?php require_role('supervisor');$pageTitle='Session Requests and Records';$pageSubtitle='Approve appointments and document supervision outcomes';$sessions=db_all("SELECT s.*,u.full_name student_name,p.title project_title FROM sessions s JOIN projects p ON p.id=s.project_id JOIN users u ON u.id=p.student_id WHERE p.supervisor_id=? ORDER BY CASE WHEN s.status='requested' THEN 0 ELSE 1 END,s.scheduled_at DESC",[current_user()['id']]);include __DIR__.'/../includes/layout_top.php'; ?>
<div class="card"><div class="card-header"><div><h2>Supervision session workflow</h2><p>Approve or reschedule requests, then complete the record after the meeting.</p></div></div><?php if(!$sessions):?><div class="empty-state">No session records are available.</div><?php else:foreach($sessions as $s):?><div class="card" style="background:#fbfcff"><div class="card-header"><div><h3><?= e($s['student_name']) ?> · <?= e(format_date($s['scheduled_at'])) ?></h3><p><?= e($s['project_title']) ?></p></div><span class="badge <?= status_class($s['status']) ?>"><?= e($s['status']) ?></span></div><p><strong>Agenda:</strong> <?= e($s['agenda']) ?></p><p class="muted"><?= e(ucfirst($s['mode'])) ?> · <?= e($s['venue_or_link']) ?></p><?php if($s['status']==='requested'):?><form class="form-grid" method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="session_decision"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><div class="form-group"><label>Decision</label><select name="status"><option value="approved">Approve</option><option value="rescheduled">Reschedule</option><option value="rejected">Reject</option></select></div><div class="form-group"><label>Confirmed/new date</label><input type="datetime-local" name="scheduled_at" value="<?= e(date('Y-m-d\TH:i',strtotime($s['scheduled_at']))) ?>"></div><div class="form-group full"><label>Venue or link</label><input name="venue_or_link" value="<?= e($s['venue_or_link']) ?>"></div><div class="form-group full"><button class="button" type="submit">Save scheduling decision</button></div></form><?php elseif(in_array($s['status'],['approved','rescheduled'],true)):?><form method="post" action="<?= e(url('actions.php')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="complete_session"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><div class="form-grid"><div class="form-group full"><label>Supervisor feedback</label><textarea name="supervisor_feedback" required placeholder="Summarise strengths, corrections and guidance provided."></textarea></div><div class="form-group"><label>Decisions reached</label><textarea name="decisions" required></textarea></div><div class="form-group"><label>Student action items</label><textarea name="action_items" required></textarea></div><div class="form-group"><label>Proposed next session</label><input type="datetime-local" name="next_session_date"></div><div class="form-group" style="display:flex;align-items:end"><button class="button" type="submit">Complete session record</button></div></div></form><?php elseif($s['status']==='completed'):?><div class="split-grid"><div class="callout"><strong>Feedback</strong><br><?= e($s['supervisor_feedback']) ?><br><br><strong>Decisions</strong><br><?= e($s['decisions']) ?></div><div class="callout"><strong>Action items</strong><br><?= e($s['action_items']) ?><br><br><strong>Next session</strong><br><?= e(format_date($s['next_session_date'])) ?></div></div><?php endif;?></div><?php endforeach;endif;?></div>
<?php include __DIR__.'/../includes/layout_bottom.php'; ?>
